import{_ as d,o as t,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Error reasons","description":"","frontmatter":{},"headers":[],"relativePath":"reference/errors.md","filePath":"reference/errors.md","lastUpdated":1793741124000}'),c={name:"reference/errors.md"};function a(n,e,s,i,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="error-reasons" tabindex="-1">Error reasons <a class="header-anchor" href="#error-reasons" aria-label="Permalink to &quot;Error reasons&quot;">​</a></h1><p>Every failure in the four packages carries a stable reason string with a prefix that says what kind of failure it is. Code matches on the string; the UI maps it to words. This page lists each reason the packages throw or report, collected from <code>packages/*/src</code>.</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Means</th></tr></thead><tbody><tr><td><code>denied:</code></td><td>A policy or the user said no. Retrying the same request will not help.</td></tr><tr><td><code>invalid:</code></td><td>The input is malformed or names something that does not exist.</td></tr><tr><td><code>unavailable:</code></td><td>Something needed is missing or unreachable right now: a backend, a server, a provider.</td></tr></tbody></table><p>Thrown reasons are the <code>message</code> of an <code>Error</code>. A few carry a detail after a space (<code>denied:scheme http:</code>), so match on the part before the first space.</p><h2 id="thrown-errors" tabindex="-1">Thrown errors <a class="header-anchor" href="#thrown-errors" aria-label="Permalink to &quot;Thrown errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reason</th><th>Package</th><th>Thrown by</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid:pointer</code></td><td><code>@kernl/core</code></td><td><code>decodePointer</code></td><td>The input is not an <code>naddr</code>, <code>nevent</code>, <code>note</code>, 64-hex event id or coordinate.</td></tr><tr><td><code>unavailable:manifest</code></td><td><code>@kernl/core</code></td><td><code>fetchManifestEvent</code>, so <code>Kernl.resolve</code></td><td>No relay in the hints or the <code>apps</code> tier returned the manifest event.</td></tr><tr><td><code>unavailable:blob</code></td><td><code>@kernl/core</code></td><td><code>defaultFetchBlob</code>, <code>resolveApplet</code></td><td>No server returned the artifact bytes. kehto&#39;s <code>blob-unavailable</code> maps here.</td></tr><tr><td><code>invalid:invalid-signature</code>, <code>invalid:invalid-manifest</code>, <code>invalid:aggregate-mismatch</code>, <code>invalid:blob-hash-mismatch</code>, <code>invalid:missing-index</code></td><td><code>@kernl/core</code></td><td><code>resolveApplet</code></td><td>Verification failed. The part after <code>invalid:</code> is kehto&#39;s <code>NappletResolutionErrorCode</code>. Nothing runs.</td></tr><tr><td><code>invalid:unresolved</code></td><td><code>@kernl/core</code></td><td><code>Kernl.plan</code></td><td>The summary was not produced by this shell&#39;s <code>resolve</code>, so no verified bytes are held for it.</td></tr><tr><td><code>denied:blocked</code></td><td><code>@kernl/core</code></td><td><code>Kernl.plan</code></td><td>The user blocked this applet identity.</td></tr><tr><td><code>denied:nested-frame</code></td><td><code>@kernl/guard</code>, <code>@kernl/core</code></td><td><code>assertAppletHasNoFrame</code>, so <code>planMount</code> and <code>Kernl.plan</code>; in the applet&#39;s realm, the frame lock</td><td>The verified markup contains an <code>iframe</code>, <code>frame</code>, <code>frameset</code>, <code>object</code>, <code>embed</code>, <code>portal</code> or <code>fencedframe</code> element, so the applet is not mounted. Inside a running applet the frame lock throws it as a <code>TypeError</code> when applet code tries to create a frame by element factory or HTML string (<a href="./../decisions#d-014">D-014</a>).</td></tr><tr><td><code>unavailable:frame-lock</code></td><td><code>@kernl/core</code></td><td><code>planMount</code>, so <code>Kernl.plan</code></td><td>The srcdoc kehto prepared does not contain the CSP meta and namespace prelude where kernl expects them, so the frame lock cannot be inserted and the applet is not mounted. Seen only with a kehto release whose output changed.</td></tr><tr><td><code>invalid:frame-detached</code></td><td><code>@kernl/core</code></td><td><code>mountApplet</code>, so <code>Kernl.mount</code></td><td>The frame has no <code>contentWindow</code>; it is not in the document.</td></tr><tr><td><code>invalid:domain</code></td><td><code>@kernl/core</code></td><td><code>Grants.allowDomain</code></td><td>The shell does not offer this domain in its current configuration.</td></tr><tr><td><code>denied:baseline-domain</code></td><td><code>@kernl/core</code></td><td><code>Grants.revokeDomain</code></td><td>Baseline domains (<code>shell</code>, <code>inc</code>, <code>theme</code>, <code>storage</code>) cannot be revoked.</td></tr><tr><td><code>denied:plaintext-key-persistence</code></td><td><code>@kernl/core</code></td><td><code>KernlAccountManager.addAccount</code></td><td>The account type stores a raw secret key (<code>PLAINTEXT_KEY_ACCOUNT_TYPES</code>).</td></tr><tr><td><code>invalid:relay-url</code></td><td><code>@kernl/core</code></td><td><code>RelayTiers.add</code></td><td>The URL is not <code>ws://</code> or <code>wss://</code>.</td></tr><tr><td><code>denied:read-only</code></td><td><code>@kernl/core</code></td><td>the outbox service&#39;s signer</td><td>The session cannot sign, so an outbox publish is refused.</td></tr><tr><td><code>denied:consent</code></td><td><code>@kernl/core</code></td><td><code>createSigningConsent</code>, through the window signer (<code>relay.publish</code>) or the outbox gate (<code>outbox.publish</code>)</td><td>An applet window asked to sign a destructive kind (any replaceable or addressable kind, 5 or 62) and the user denied or dismissed <code>host.presentConsent</code>. Nothing was signed or published.</td></tr><tr><td><code>denied:unknown-applet</code></td><td><code>@kernl/core</code></td><td><code>createSigningConsent</code></td><td>A destructive write from a window the shell did not mount.</td></tr><tr><td><code>denied:signed-out</code></td><td><code>@kernl/core</code></td><td><code>createSigningConsent</code></td><td>A destructive write (in practice an <code>outbox.publish</code>) while nobody is signed in.</td></tr><tr><td><code>invalid:event-kind</code></td><td><code>@kernl/core</code></td><td><code>createSigningConsent</code></td><td>The event&#39;s <code>kind</code> is not a number.</td></tr><tr><td><code>unavailable:sign-in-required</code></td><td><code>@kernl/core</code></td><td><code>createDefaultMessaging</code>&#39;s <code>createBackend</code>; <code>MessagingRegistry.enable</code></td><td><code>private</code> or <code>legacy</code> while no account is active (<code>MESSAGING_UNAVAILABLE_REASONS</code>).</td></tr><tr><td><code>unavailable:signer-cannot-encrypt</code></td><td><code>@kernl/core</code></td><td><code>createDefaultMessaging</code>&#39;s <code>createBackend</code>; <code>MessagingRegistry.enable</code></td><td>The active account&#39;s signer has no <code>nip44</code> (<code>private</code>) or no <code>nip04</code> (<code>legacy</code>); a read-only account is the usual case.</td></tr><tr><td><code>unavailable:no-runtime</code></td><td><code>@kernl/core</code></td><td><code>createDefaultMessaging</code>&#39;s <code>createBackend</code>; <code>MessagingRegistry.enable</code></td><td><code>ratchet</code>: no double-ratchet runtime is supplied.</td></tr><tr><td><code>invalid:duplicate-provider</code></td><td><code>@kernl/messaging</code></td><td><code>MessagingRegistry.register</code></td><td>A provider with this id is already registered.</td></tr><tr><td><code>invalid:unknown-provider</code></td><td><code>@kernl/messaging</code></td><td><code>MessagingRegistry.enable</code>, <code>disable</code>; the composite backend</td><td>No provider has this id, or a namespaced id, cursor or <code>provider</code> hint names no enabled provider.</td></tr><tr><td><code>unavailable:&lt;reason&gt;</code></td><td><code>@kernl/messaging</code></td><td><code>MessagingRegistry.enable</code></td><td>The provider&#39;s <code>availability()</code> is false; <code>&lt;reason&gt;</code> is the bare word it reported.</td></tr><tr><td><code>invalid:provider-not-enabled</code></td><td><code>@kernl/messaging</code></td><td><code>MessagingRegistry.setDefault</code></td><td>Only an enabled provider can be the default.</td></tr><tr><td><code>unavailable:no-default-provider</code></td><td><code>@kernl/messaging</code></td><td>composite <code>send</code></td><td>The request names no conversation and no provider, and there is no enabled default.</td></tr><tr><td><code>invalid:no-recipients</code>, <code>invalid:unknown-conversation</code>, <code>unavailable:offline</code></td><td><code>@kernl/messaging</code></td><td><code>createMemoryBackend</code> <code>send</code></td><td>No recipient besides the owner; a <code>conversationId</code> the backend does not hold; the backend was created with <code>available: false</code>.</td></tr><tr><td><code>invalid:recipient</code>, <code>invalid:groups-unsupported</code>, <code>unavailable:offline</code></td><td><code>@kernl/core</code></td><td><code>createPrivateMessagesBackend</code>, <code>createLegacyMessagesBackend</code> <code>send</code></td><td>The recipient is not a public key; the legacy backend got more than one correspondent; no relay accepted the message.</td></tr><tr><td><code>invalid:locator</code></td><td><code>@kernl/bridges</code></td><td><code>parseLocator</code></td><td>Not a locator, or a malformed web, NZB, Soulseek or mail locator.</td></tr><tr><td><code>invalid:magnet-missing-hash</code></td><td><code>@kernl/bridges</code></td><td><code>parseLocator</code></td><td>A magnet without a <code>urn:btih:</code> hash.</td></tr><tr><td><code>invalid:locator-missing-&lt;field&gt;</code></td><td><code>@kernl/bridges</code></td><td>the torrent, NZB, Soulseek and mail bridges</td><td>The locator lacks <code>infoHash</code>, <code>url</code>, <code>user</code>, <code>path</code> or <code>address</code>.</td></tr><tr><td><code>invalid:nzb-not-https</code></td><td><code>@kernl/bridges</code></td><td>the NZB backend from <code>createHandoffBackends</code></td><td>The NZB document is not served over <code>https</code>, so it is not handed off and nothing is opened.</td></tr><tr><td><code>invalid:duplicate-bridge &lt;id&gt;</code>, <code>invalid:scheme-taken &lt;scheme&gt;</code></td><td><code>@kernl/bridges</code></td><td><code>BridgeRegistry.register</code></td><td>A bridge with this id, or one serving this scheme, is already registered.</td></tr><tr><td><code>unavailable:no-bridge</code></td><td><code>@kernl/bridges</code></td><td><code>BridgeRegistry.resolve</code></td><td>No bridge serves the scheme.</td></tr><tr><td><code>unavailable:no-backend</code></td><td><code>@kernl/bridges</code></td><td>the four backend-driven bridges</td><td>The bridge was created without a backend. <code>availability().reason</code> is the bare <code>no-backend</code>. In the composed shell the four have hand-off backends; a registry built from <code>createDefaultBridges()</code> without a <code>handoff</code> opener reports this.</td></tr><tr><td><code>denied:bridge</code></td><td><code>@kernl/bridges</code></td><td><code>BridgeRegistry.resolve</code></td><td>The registry&#39;s <code>authorize</code> hook returned false. The composed shell has none.</td></tr><tr><td><code>denied:scheme &lt;protocol&gt;</code></td><td><code>@kernl/bridges</code></td><td>HTTP bridge</td><td>The URL&#39;s scheme is not in <code>allowedSchemes</code>.</td></tr><tr><td><code>denied:private-address &lt;host&gt;</code>, <code>denied:private-address &lt;host&gt; -&gt; &lt;ip&gt;</code></td><td><code>@kernl/bridges</code></td><td>HTTP bridge</td><td>The host is a blocked name or a private literal; the second form comes from a <code>resolveHost</code> result.</td></tr><tr><td><code>denied:too-many-redirects</code></td><td><code>@kernl/bridges</code></td><td>HTTP bridge</td><td>More than <code>maxRedirects</code> hops.</td></tr><tr><td><code>denied:redirect-unverifiable</code></td><td><code>@kernl/bridges</code></td><td>HTTP bridge</td><td>In a browser, <code>fetch</code> with <code>redirect: &#39;manual&#39;</code> returns an opaque redirect whose target the bridge cannot read, so it cannot re-check the next hop and refuses. In Node and on servers redirects are followed and checked.</td></tr><tr><td><code>invalid:redirect</code></td><td><code>@kernl/bridges</code></td><td>HTTP bridge</td><td>A redirect without a usable <code>Location</code>.</td></tr><tr><td><code>denied:too-large</code></td><td><code>@kernl/bridges</code></td><td>HTTP bridge</td><td><code>content-length</code> or the streamed body exceeds <code>maxBytes</code>.</td></tr><tr><td><code>unavailable:timeout</code>, <code>unavailable:aborted</code>, <code>unavailable:network &lt;message&gt;</code></td><td><code>@kernl/bridges</code></td><td>HTTP bridge</td><td>The time limit expired, the caller cancelled, or <code>fetch</code> failed for another reason. In a browser a CORS refusal and a network failure are the same <code>TypeError</code>, so both surface as <code>unavailable:network Failed to fetch</code>.</td></tr><tr><td><code>unavailable:network &lt;type&gt; response</code></td><td><code>@kernl/bridges</code></td><td>HTTP bridge</td><td>Any status-0 answer other than an opaque redirect, for example <code>unavailable:network opaque response</code>.</td></tr></tbody></table><p>Apart from <code>assertAppletHasNoFrame</code>, <code>@kernl/guard</code> throws nothing. Its decisions are events.</p><h2 id="guard-event-reasons" tabindex="-1">Guard event reasons <a class="header-anchor" href="#guard-event-reasons" aria-label="Permalink to &quot;Guard event reasons&quot;">​</a></h2><p>The guard reports each non-pass decision as a <code>GuardEvent</code> with a <code>disposition</code> (<code>defer</code>, <code>reject</code>, <code>quarantine</code>, <code>flag</code>) and one of these reasons. They reach the user through <code>kernl.guard.events$</code> and the shell&#39;s guard panel. The numbers are per profile; see <a href="./../concepts/guard#profiles">Guard</a>.</p><p>For an applet&#39;s port traffic these layers observe each envelope just before kehto dispatches it but cannot hold it (<a href="./../decisions#d-012">D-012</a>): an event records what happened. Two reasons change the outcome. <code>size:&lt;class&gt;</code> makes kehto&#39;s runtime firewall refuse that envelope (<code>refuseCurrentDispatch</code>), and <code>quarantine</code> revokes the binding, which also stops the envelope that crossed the limit. Otherwise <code>defer</code> and <code>reject</code> hold or drop only the window-level <code>hello</code>.</p><p>Refusals by kehto&#39;s runtime firewall (the per-class rates and the startup burst) are not guard events: kehto answers the applet with an error whose message starts <code>firewall:</code>, and <code>ShellAdapter</code> does not forward the runtime&#39;s firewall events to the host (<a href="./../alpha-status#upstream-gaps">upstream gap 1</a>). The focus firewall&#39;s <code>rate:&lt;class&gt;</code> events count the same rates, so the user still sees an applet that runs out.</p><table tabindex="0"><thead><tr><th>Reason</th><th>Emitted by</th><th>Disposition</th><th>Meaning</th></tr></thead><tbody><tr><td><code>flood:burst</code></td><td>ingress guard (<code>ingress-guard.ts</code>)</td><td><code>defer</code></td><td>More messages in one second than <code>ingressBurst</code> allows. A <code>hello</code> is held; for port traffic this is a report.</td></tr><tr><td><code>flood:queue-full</code></td><td>ingress guard</td><td><code>reject</code></td><td>More than <code>ingressQueue</code> messages over the burst. A <code>hello</code> is dropped; for port traffic this is a report.</td></tr><tr><td><code>flood:quarantine</code></td><td>ingress guard</td><td><code>quarantine</code></td><td><code>quarantineThreshold</code> messages in a rolling 10 s, or any message from a window already quarantined. The binding is revoked.</td></tr><tr><td><code>flood:hidden-resource</code></td><td>ingress guard</td><td><code>quarantine</code></td><td>A hidden window made more <code>resource.*</code> requests than <code>hiddenResourceAllowance</code>. The binding is revoked.</td></tr><tr><td><code>size:&lt;class&gt;</code></td><td>ingress guard</td><td><code>reject</code></td><td>The envelope is over the size cap for <code>resource:bytes</code>, <code>relay:subscribe</code> or <code>outbox:subscribe</code>. In the composed shell the runtime firewall refuses it before dispatch, so the applet receives a <code>firewall:</code> error and nothing is fetched.</td></tr><tr><td><code>defer:queue-full</code></td><td>visibility gate (<code>visibility-gate.ts</code>)</td><td><code>reject</code></td><td>The hidden window&#39;s deferral queue is full. Only the window-level <code>hello</code> passes through the gate.</td></tr><tr><td><code>rate:&lt;class&gt;</code></td><td>focus firewall (<code>focus-firewall.ts</code>)</td><td><code>reject</code>, or <code>flag</code> when the rate&#39;s action is <code>flag</code></td><td>kehto&#39;s <code>rate:opclass</code>, <code>rate:global</code> or <code>rate:default</code> rule fired; the reason names the class, for example <code>rate:relay:publish</code>.</td></tr><tr><td><code>matcher:&lt;id&gt;</code></td><td>focus firewall</td><td><code>reject</code></td><td>A kehto content matcher fired; the rule id is passed through unchanged. The guard&#39;s own matchers are <code>size:resource:bytes</code>, <code>size:relay:subscribe</code> and <code>size:outbox:subscribe</code>, and in the composed shell they cannot fire: the ingress guard rejects the same envelopes with <code>size:&lt;class&gt;</code> first, and the focus firewall sees only what it passed. A caller that runs the focus firewall alone can see <code>matcher:size:&lt;class&gt;</code>.</td></tr><tr><td><code>policy:deny</code></td><td>focus firewall</td><td><code>reject</code></td><td>The applet&#39;s policy in the guard&#39;s own firewall configuration is <code>deny</code>. kernl sets no policy there, so this appears only if a caller set one.</td></tr><tr><td><code>prompt:&lt;ruleId&gt;</code></td><td>focus firewall</td><td><code>reject</code></td><td>kehto&#39;s engine asked for a prompt (for example <code>prompt:policy:ask</code>); the guard has no UI and treats it as a rejection.</td></tr></tbody></table><h2 id="revocation-reasons" tabindex="-1">Revocation reasons <a class="header-anchor" href="#revocation-reasons" aria-label="Permalink to &quot;Revocation reasons&quot;">​</a></h2><p><code>KernlHost.onRevoked(windowId, reason)</code> receives kehto&#39;s revocation reasons (<code>window-message</code>, <code>second-hello</code>, <code>invalid-hello</code>, <code>second-load</code>, <code>port-closed</code>, <code>host</code>) or <code>quarantine</code> when the guard quarantined the window. See <a href="./../concepts/architecture#the-mount-path">Architecture</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./api">API reference</a>: each function&#39;s JSDoc names the reasons it throws.</li><li><a href="./../guides/troubleshooting">Troubleshooting</a></li></ul>',16)])])}const g=d(c,[["render",a]]);export{p as __pageData,g as default};
